/* ------------------------------------------------------------------ */
/* DefaultPortLabel — LabeledPort's built-in label fill (D1, 2026-09-16: */
/* plain text via EditableText, not CodeField). A host that wants a     */
/* different editor passes `labelSlot` instead — see LabeledPortProps.   */
/* ------------------------------------------------------------------ */

/** Below this, the editor grows no narrower — a 1-2 char value still reads
 *  as a text field, not a single blinking-caret sliver. */
const MIN_LABEL_COLUMNS = 3;

/**
 * Click-to-edit. Two MUTUALLY EXCLUSIVE branches, never both mounted: at
 * rest a plain `<span>` (`port-label-display`), while editing a single-line
 * `CodeEditor` — swapping the element TYPE at the same tree position, so
 * React unmounts one and mounts the other rather than layering one over the
 * other (F-1 item 1/2: "the actual ports should basically look identical
 * ... when you are in multi line edit mode, the display text shouldn't show
 * any more"). Local `value` mirrors `children` whenever not mid-edit (so an
 * unwired label simply reflects whatever the host passes), and
 * `onLabelWrite` fires live on every keystroke — the same "fired on every
 * keystroke" contract the donor's `CodeField`-backed `PortLabel` documented.
 * Escape reverts to the value captured at the moment editing started.
 */
function DefaultPortLabel({
  children = "",
  direction = "input",
  textSize = "sm",
  disabled = false,
  onLabelWrite,
  placeholder,
  language,
  className,
  style,
}: {
  children?: string;
  direction?: PortDirection;
  textSize?: PortTextSize;
  disabled?: boolean;
  onLabelWrite?(value: string): void;
  placeholder?: string;
  language?: LanguageSupport;
  className?: string;
  style?: CSSProperties;
}) {
  const [editing, setEditing] = useState(false);
  const [value, setValue] = useState(children);
  const snapshotRef = useRef(children);

  // Mirrors the host's `children` whenever this field isn't mid-edit — the
  // same "reverts to children" contract the donor's unwired PortLabel had.
  useEffect(() => {
    if (!editing) setValue(children);
  }, [children, editing]);

  // F-1's own acceptance test: `getComputedStyle().fontSize` on the resting
  // label and on the editor's own text must be EQUAL. Both branches below
  // read this SAME number — there is no second ladder to drift out of sync
  // with (the bug Zach saw was two DIFFERENT components each picking their
  // own size; one component reading one variable can't repeat that).
  const fontSizePx = PORT_TEXT_SIZES[textSize];
  // Text hugs the dot on the side the label actually flows toward — same
  // intent `direction` carried on the donor's CodeField.
  const align = direction === "output" ? "right" : "left";
  const exitEditing = () => setEditing(false);

  if (editing && !disabled) {
    return (
      <span data-slot="port-label" data-direction={direction} data-editing="true" className={cn("flex min-w-0 items-center", className)} style={style}>
        <CodeEditor
          value={value}
          onWrite={(next) => {
            setValue(next);
            onLabelWrite?.(next);
          }}
          // Loses focus (click elsewhere, tab away) commits and exits —
          // the ONE path `onEnter`/`onEscape` below don't already cover.
          onEditEnd={exitEditing}
          multiline={false}
          language={language}
          fontSizePx={fontSizePx}
          align={align}
          // An <input>-like port label: cut at the edge, no scrollbar —
          // same convention `LabeledPort.stories.tsx`'s `CodeLabel` story
          // already established for a CodeEditor filling this slot.
          overflow="clip"
          columns={Math.max(MIN_LABEL_COLUMNS, value.length)}
          autoFocus="select"
          onEnter={exitEditing}
          onEscape={() => {
            setValue(snapshotRef.current);
            onLabelWrite?.(snapshotRef.current);
            exitEditing();
          }}
        />
      </span>
    );
  }

  const isEmpty = value === "";
  return (
    <span
      data-slot="port-label"
      data-direction={direction}
      data-editing="false"
      className={cn("flex min-w-0 items-center", className)}
      style={style}
      onClick={() => {
        if (disabled) return;
        snapshotRef.current = value;
        setEditing(true);
      }}
    >
      {/* Truthful rendering: a long value still ellipsizes visually, but
       *  the full string stays one hover away via `title` — the same
       *  recipe `editableText.tsx`'s own `editable-text-content` span
       *  uses, not reinvented here. */}
      <span
        data-slot="port-label-display"
        title={!isEmpty ? value : undefined}
        data-placeholder={isEmpty && placeholder ? "" : undefined}
        style={{
          fontSize: fontSizePx,
          display: "block",
          minWidth: 0,
          maxWidth: "100%",
          whiteSpace: "nowrap",
          overflow: "hidden",
          textOverflow: "ellipsis",
          textAlign: align,
          opacity: isEmpty ? 0.5 : undefined,
        }}
      >
        {isEmpty ? (placeholder ?? "") : value}
      </span>
    </span>
  );
}

/* ------------------------------------------------------------------ */
/* LabeledPort — Port + the label slot + the secondary slot, paired as */
/* flex siblings for a standalone specimen.                            */
/* ------------------------------------------------------------------ */

export interface LabeledPortProps extends ComponentProps<"div"> {
  /** The label slot's entire content, one line. */
  children?: string;
  direction?: PortDirection;
  edge?: BlockSide;
  diameter?: PortSize;
  /** Sensible default is `inwardTextLayout(edge)` when omitted. */
  textLayout?: PortTextLayout;
  textSize?: PortTextSize;
  state?: PortState;
  hidden?: boolean;
  dimmed?: boolean;
  hinting?: boolean;
  /**
   * The label slot's placement, reaching PAST `textLayout` (the preset over
   * exactly these three). Omit any of them and the preset decides; set one
   * and it wins. `offsetX` is + away from the dot along the origin's own
   * axis, `offsetY` is + DOWN, and both may be negative.
   */
  labelOrigin?: SlotOrigin;
  labelAlign?: SlotAlign;
  labelOffsetX?: number;
  labelOffsetY?: number;
  /** The secondary slot's placement — the same three controls over the
   *  same `SlotOrigin` type, with `secondarySlotLayout` as its preset. */
  secondaryOrigin?: SlotOrigin;
  secondaryAlign?: SlotAlign;
  secondaryOffsetX?: number;
  secondaryOffsetY?: number;
  /**
   * Content for the LABEL position. Present — INCLUDING empty — replaces
   * the built-in `DefaultPortLabel` entirely, same position, same lift.
   * Absent means the built-in field. This is the seam Phase 4's multi-line
   * lane editor (and, later, a real CodeField) attaches through: swap what
   * fills this slot without touching `LabeledPort`'s placement math at all.
   */
  labelSlot?: ReactNode;
  /** Content for the SECONDARY position, same present-beats-absent
   *  contract as `labelSlot`. There is no `producers`-count fallback here
   *  (D3) — an unset secondary slot renders nothing, full stop. */
  secondarySlot?: ReactNode;
  /** Where an explicit `secondarySlot` sits. Omit for the AUTO default —
   * the corner opposite wherever the label is actually flowing. */
  secondarySlotLayout?: SecondarySlotLayout;
  /** No caret, no edits on the label's built-in field. */
  disabled?: boolean;
  /** Fired on every keystroke of the built-in label field. */
  onLabelWrite?(value: string): void;
  /** Shown in the built-in label field when `children` is empty. */
  placeholder?: string;
  /**
   * The built-in label field's syntax parser while editing (F-1/F-3), e.g.
   * `python()` from `@codemirror/lang-python` — the same prop `CodeEditor`
   * itself already exposes, forwarded straight through. Omit for plain
   * text. Ignored when `labelSlot` is set — that override owns its own
   * editor entirely, same as `CodeLabel` story's pattern below.
   */
  labelLanguage?: LanguageSupport;
}

/**
 * The flex-row pairing of `Port` + its two slots, for a standalone specimen
 * — a real host mounting a port on a real block wall would position the
 * dot and the label independently instead (the donor package's `anchored`
 * mode, deliberately not ported here — see this file's module doc).
 */
export function LabeledPort({
  direction = "input",
  edge = "left",
  diameter = "md",
  textLayout,
  textSize = "sm",
  state = "empty",
  hidden = false,
  dimmed = false,
  hinting = false,
  labelOrigin,
  labelAlign,
  labelOffsetX,
  labelOffsetY,
  secondaryOrigin,
  secondaryAlign,
  secondaryOffsetX,
  secondaryOffsetY,
  labelSlot,
  secondarySlot,
  secondarySlotLayout,
  disabled = false,
  onLabelWrite,
  placeholder,
  labelLanguage,
  className,
  style,
  children = "",
  ...props
}: LabeledPortProps) {
  if (hidden) return null;
  const resolvedTextLayout = textLayout ?? inwardTextLayout(edge);
  const diameterPx = typeof diameter === "number" ? diameter : PORT_DIAMETERS[diameter];
  const resolvedSecondaryLayout = secondarySlotLayout ?? defaultSecondarySlotLayout(resolvedTextLayout);

  // The named layout is the PRESET; an explicit origin/offset reaches past
  // it — the unified (origin, x, y) model every host and every saved shape
  // ultimately speaks (see port.layout.ts's own module doc).
  const textLayoutPreset = TEXT_LAYOUT_AS_PLACEMENT[resolvedTextLayout];
  const labelPlacement: SlotPlacement = {
    origin: labelOrigin ?? textLayoutPreset.origin,
    align: labelAlign ?? textLayoutPreset.align,
    offsetX: labelOffsetX ?? 0,
    offsetY: labelOffsetY ?? textLayoutPreset.offsetY,
  };
  const secondaryPlacement: SlotPlacement = {
    origin: secondaryOrigin ?? SECONDARY_LAYOUT_AS_ORIGIN[resolvedSecondaryLayout],
    align: secondaryAlign ?? "center",
    offsetX: secondaryOffsetX ?? 0,
    offsetY: secondaryOffsetY ?? 0,
  };

  // A host-given `secondarySlot` wins outright — INCLUDING when it is
  // empty (`<></>`), which is what makes an emptied slot stay empty rather
  // than reverting to some default. There is no `producers` fallback (D3).
  const resolvedSecondarySlot: ReactNode = secondarySlot !== undefined ? secondarySlot : undefined;

  // B4 fix: the ROOT box is exactly the dot's own box (diameterPx square),
  // never the label's. Both slots are absolutely positioned OFF that box
  // via `slotPlacementStyle` — the SAME function the secondary slot always
  // used — instead of the old flex-row pairing (`originFlexDirection` +
  // a `flexOffsetTransform` computed as a delta from the ROW's own centre).
  // That old approach silently assumed the row's cross-centre (what
  // `items-center` actually aligns) equals the DOT's centre — true only
  // when the label is exactly as tall as the dot. A host that centres this
  // component as a unit (a PortEdge rail's `alignItems: "center"`, in
  // particular) was therefore centring the COMBINED dot+label box, so the
  // dot itself drifted off the rail's centre line the instant a label was
  // taller than the dot (docs bug B4). Sizing the root to the dot alone
  // makes that impossible by construction: whatever centres THIS component
  // centres the dot, and the label — now an overlay, not a flow sibling —
  // extends outward from wherever it actually sits, at any height.
  const labelSlotStyle = slotPlacementStyle(labelPlacement, { w: diameterPx, h: diameterPx }, PORT_LABEL_GAP);

  return (
    <div
      data-slot="port"
      data-state={state}
      data-direction={direction}
      data-edge={edge}
      data-text-layout={resolvedTextLayout}
      className={cn("relative inline-flex shrink-0", className)}
      style={{ width: diameterPx, height: diameterPx, ...style }}
      {...props}
    >
      <Port state={state} diameter={diameter} dimmed={dimmed} hinting={hinting} />
      {labelSlot !== undefined ? (
        <span data-slot="port-label-slot" className="absolute" style={labelSlotStyle}>
          {labelSlot}
        </span>
      ) : (
        <DefaultPortLabel
          direction={direction}
          textSize={textSize}
          disabled={disabled}
          onLabelWrite={onLabelWrite}
          placeholder={placeholder}
          language={labelLanguage}
          className="absolute"
          style={labelSlotStyle}
        >
          {children}
        </DefaultPortLabel>
      )}
      {resolvedSecondarySlot != null && (
        // F-6: "the slot position may change but its always just a single
        // horizontal text line, similar to the primary label slot" —
        // `whiteSpace: nowrap` is the structural guarantee (Zach's
        // screenshot showed "Event 4" wrapping to two lines the instant a
        // host's own width constraint squeezed this slot; a shrink-to-fit
        // absolute box never needs to wrap ON ITS OWN, but nothing stopped
        // an ANCESTOR from imposing one — see `SecondarySlot` story's
        // `SingleLineContent` case). `display: inline-flex` + `alignItems:
        // center` keeps arbitrary content (a `<Pill>`, an icon+digit pair)
        // vertically centred on one line rather than stacking as block
        // children would.
        <span
          data-slot="port-secondary-slot"
          className="pointer-events-none absolute inline-flex items-center whitespace-nowrap"
          style={slotPlacementStyle(secondaryPlacement, { w: diameterPx, h: diameterPx }, PORT_SECONDARY_SLOT_GAP_PX)}
        >
          {resolvedSecondarySlot}
        </span>
      )}
    </div>
  );
}

/**
 * src/components/port.layout.ts — Port's portable geometry, ported by value
 * from packages/bbox-ui/src/port.layout.ts (docs/PORT-EDGE-PLAN.md's Phase 1).
 *
 * Kept: every constant/type/function that is pure GEOMETRY — the dot's
 * sizing, the unified slot-placement model (`SlotOrigin`/`SlotAlign`/
 * `SlotPlacement`/`slotPlacementStyle`), the `PortTextLayout` compatibility
 * table, and the direction/edge helpers Port and LabeledPort both read.
 *
 * Dropped, deliberately (docs/PORT-EDGE-PLAN.md's "Left behind" list): the
 * wall-anchor geometry (`portAnchor`, `portDotPlacement`,
 * `PORT_DOT_CENTER_TRANSFORM`, `portLabelOut`, `portLabelPlacement`,
 * `BLOCK_BORDER_PX`) — this app has no `anchored` mode, every specimen here
 * is a standalone flex pairing, exactly what a Storybook story already is.
 * Also dropped: the row-pitch constants (`PORT_ROW_PITCH_PX` and friends,
 * for a wall-mounted lane's row alignment — Phase 4, out of scope here) and
 * the `size` cascade rung (`PortSizeRung` + friends — D4: `diameter`/
 * `textSize` are direct props in this reset lane, no header hands a size
 * down). Nothing here imports `./layout` (`SIMPLE_BLOCK`) — dropping the
 * wall-anchor math is what makes that import unnecessary.
 *
 * DONOR LINES for the pieces that did travel (donor read 2026-09-17, 670
 * lines, same repo — so every number below is checkable with one `sed`):
 *   • `port.layout.ts:31`     `PORT_DIAMETERS` (8/12/18).
 *   • `port.layout.ts:40-41`  `PORT_SURFACE_RING_PX` / `PORT_STATE_RING_PX`.
 *   • `port.layout.ts:508`    `SlotOrigin`.
 *   • `port.layout.ts:549`    `SlotAlign`.
 *   • `port.layout.ts:590+`   `slotPlacementStyle`, the placement model.
 *
 * NO PRIOR ART IS CLAIMED for anything in this file. The slot-placement
 * model is a local convention over CSS absolute positioning, and the dot
 * diameters were measured against the real SystemSketch app rather than
 * derived — there is no algorithm here and no paper to point at. The one
 * genuinely published spec this app leans on is CSS content-distribution,
 * and that lives in `portEdge.layout.ts`'s `mainAxisPositions`, not here.
 */
import type { CSSProperties } from "react";

/* ------------------------------------------------------------------ */
/* Port dot — geometry re-measured against the real SystemSketch app   */
/* (see the donor file's own header for provenance).                   */
/* ------------------------------------------------------------------ */

export const PORT_DIAMETERS = { sm: 8, md: 12, lg: 18 } as const;
export type PortSize = keyof typeof PORT_DIAMETERS | number; // number = "Exact"

export const PORT_DIAMETER_LABELS: Record<keyof typeof PORT_DIAMETERS, string> = {
  sm: "Small",
  md: "Medium",
  lg: "Large",
};

export const PORT_SURFACE_RING_PX = 2;
export const PORT_STATE_RING_PX = 3;
// WHY: the rings are box-shadow, painted OUTSIDE the dot's layout box — any
// spacing measured from the box edge must add this or the ring eats it.
export const PORT_RING_OVERHANG_PX = PORT_SURFACE_RING_PX + PORT_STATE_RING_PX;
export const PORT_HIT_PX = 40;

/**
 * The six legacy named label placements, widened back from four in the
 * donor's own 2026-09-12 change — "Right Offset"/"Left Offset" lift the
 * label clear of a trace wire (see `TEXT_LAYOUT_AS_PLACEMENT` below).
 */
export type PortTextLayout = "top" | "bot" | "right" | "left" | "rightOffset" | "leftOffset";

export const PORT_TEXT_LAYOUTS: PortTextLayout[] = [
  "top",
  "bot",
  "right",
  "left",
  "rightOffset",
  "leftOffset",
];

export const PORT_TEXT_LAYOUT_LABELS: Record<PortTextLayout, string> = {
  top: "Top",
  bot: "Bot",
  right: "Right",
  left: "Left",
  rightOffset: "Right Offset",
  leftOffset: "Left Offset",
};

export const PORT_LABEL_GAP = 8;

/**
 * The flex row's direction for a resolved ORIGIN — so the Expert
 * `labelOrigin` control (or a host's own `edge`/`textLayout` choice) always
 * matches which side the row actually lays the label on.
 */
export function originFlexDirection(
  origin: SlotOrigin,
): "row" | "row-reverse" | "column" | "column-reverse" {
  switch (origin) {
    case "top":
      return "column-reverse"; // label above the dot
    case "bottom":
      return "column";
    case "right":
      return "row";
    case "left":
      return "row-reverse";
  }
}

/** True for the two legacy label positions that lift the label clear of a
 *  trace wire — derived from `TEXT_LAYOUT_AS_PLACEMENT`, not a second
 *  hand-written list. */
export function isOffsetTextLayout(layout: PortTextLayout): boolean {
  return TEXT_LAYOUT_AS_PLACEMENT[layout].align === "end";
}

export type PortDirection = "input" | "output";
export const PORT_DIRECTIONS: PortDirection[] = ["input", "output"];
export const PORT_DIRECTION_LABELS: Record<PortDirection, string> = {
  input: "Input",
  output: "Output",
};

export type BlockSide = "left" | "right" | "top" | "bottom";
export const BLOCK_SIDES: BlockSide[] = ["left", "right", "top", "bottom"];
export const BLOCK_SIDE_LABELS: Record<BlockSide, string> = {
  left: "Left",
  right: "Right",
  top: "Top",
  bottom: "Bottom",
};

const SIDE_FOR_DIRECTION: Record<PortDirection, BlockSide> = {
  input: "left",
  output: "right",
};

export function portSideForDirection(direction: PortDirection): BlockSide {
  return SIDE_FOR_DIRECTION[direction];
}

/** Which way the label flows from the dot by default: inward, into the
 * block's interior, away from whatever the port connects to outside. */
export function inwardTextLayout(side: BlockSide): PortTextLayout {
  switch (side) {
    case "left":
      return "right";
    case "right":
      return "left";
    case "top":
      return "bot";
    case "bottom":
      return "top";
  }
}

/** Port's own text-size rung — same four px values as EditableText's
 * ladder (`editableText.layout.ts`'s `EDITABLE_TEXT_SIZES`), so a
 * `PortTextSize` passes straight through as an `EditableTextSize` with no
 * translation table. */
export const PORT_TEXT_SIZES = { sm: 18, md: 24, lg: 36, xl: 44 } as const;
export type PortTextSize = keyof typeof PORT_TEXT_SIZES;
export const PORT_TEXT_SIZE_LABELS: Record<PortTextSize, string> = {
  sm: "Small",
  md: "Medium",
  lg: "Large",
  xl: "Extra Large",
};

/**
 * `PortDot`'s second independently-positioned slot: generic content hugging
 * a corner of the dot, closer in than the label slot's own "Offset"
 * positions.
 */
export type SecondarySlotLayout = "leftOffset" | "rightOffset" | "topOffset" | "botOffset";

export const SECONDARY_SLOT_LAYOUTS: SecondarySlotLayout[] = [
  "leftOffset",
  "rightOffset",
  "topOffset",
  "botOffset",
];

export const SECONDARY_SLOT_LAYOUT_LABELS: Record<SecondarySlotLayout, string> = {
  leftOffset: "Left Offset",
  rightOffset: "Right Offset",
  topOffset: "Top Offset",
  botOffset: "Bot Offset",
};

/** How tightly the secondary slot hugs the dot's own box — deliberately
 * smaller than `PORT_LABEL_GAP` (a badge/cue hugging a corner, not content
 * sitting flush beside the dot). */
export const PORT_SECONDARY_SLOT_GAP_PX = 6;

/** The secondary slot's AUTO default position — the corner opposite
 * wherever the label is actually flowing. Only consulted when a caller
 * omits `secondarySlotLayout` outright; an explicit value always wins. */
export function defaultSecondarySlotLayout(labelLayout: PortTextLayout): SecondarySlotLayout {
  switch (labelLayout) {
    case "left":
    case "leftOffset":
      return "rightOffset";
    case "right":
    case "rightOffset":
      return "leftOffset";
    case "top":
      return "botOffset";
    case "bot":
      return "topOffset";
  }
}

/* ------------------------------------------------------------------ */
/* THE UNIFIED SLOT PLACEMENT MODEL                                    */
/* ------------------------------------------------------------------ */

/** Which side of the dot a slot anchors to — the ORIGIN. Shared by both
 * slots; the named `PortTextLayout`/`SecondarySlotLayout` members are
 * PRESETS over (origin, offsetX, offsetY), not a parallel vocabulary. */
export type SlotOrigin = "top" | "bottom" | "left" | "right";

export const SLOT_ORIGINS: SlotOrigin[] = ["top", "bottom", "left", "right"];

export const SLOT_ORIGIN_LABELS: Record<SlotOrigin, string> = {
  top: "Top",
  bottom: "Bottom",
  left: "Left",
  right: "Right",
};

/**
 * WHICH PART OF THE SLOT is the reference point, on the axis the origin
 * leaves free — "end" is what makes "clear of the trace wire" a static
 * offset instead of one derived from the label's own (unknowable) height:
 * `translate(…, -100%)` puts the chosen edge ON the reference line whatever
 * the slot's content measures.
 */
export type SlotAlign = "start" | "center" | "end";

export const SLOT_ALIGNS: SlotAlign[] = ["start", "center", "end"];

const ALIGN_SHIFT: Record<SlotAlign, string> = {
  start: "0%",
  center: "-50%",
  end: "-100%",
};

export interface SlotPlacement {
  origin: SlotOrigin;
  align: SlotAlign;
  offsetX: number;
  offsetY: number;
}

/** A port dot's box, named so it cannot be mistaken for anything else. */
export interface PortDotBox {
  w: number;
  h: number;
}

/**
 * CSS offsets for a slot absolutely positioned against the dot's box. Plain
 * data — spreads into any host's `style` object.
 */
export interface PortLabelPlacement extends CSSProperties {
  left?: string;
  right?: string;
  top?: string;
  bottom?: string;
  transform: string;
}

/**
 * THE ONE ANCHOR RULE: the slot's content anchors by the edge FACING its
 * origin, centred on the other axis, sitting `gap` clear of the dot's
 * PAINTED ring; `offsetX`/`offsetY` then translate it from there in SCREEN
 * space (so `+x` always means "rightward on screen", on every origin).
 */
export function slotPlacementStyle(
  placement: SlotPlacement,
  dot: PortDotBox,
  gapPx: number,
  boxInsetPx: number = 0,
): PortLabelPlacement {
  const { origin, align, offsetX, offsetY } = placement;
  const shift = ALIGN_SHIFT[align];
  const outX = `${dot.w + PORT_RING_OVERHANG_PX + gapPx - boxInsetPx}px`;
  const outY = `${dot.h + PORT_RING_OVERHANG_PX + gapPx - boxInsetPx}px`;
  switch (origin) {
    case "right":
      return { left: outX, top: "50%", transform: `translate(${offsetX}px, calc(${shift} + ${offsetY}px))` };
    case "left":
      return { right: outX, top: "50%", transform: `translate(${offsetX}px, calc(${shift} + ${offsetY}px))` };
    case "top":
      return { bottom: outY, left: "50%", transform: `translate(calc(${shift} + ${offsetX}px), ${offsetY}px)` };
    case "bottom":
      return { top: outY, left: "50%", transform: `translate(calc(${shift} + ${offsetX}px), ${offsetY}px)` };
  }
}

/**
 * The six-member `PortTextLayout` as (origin, align, offsetY) — the two
 * "Offset" members are a STATIC placement: anchor the slot's bottom edge
 * (`align: "end"`) on the dot's centre line, then push it up one gap.
 * Height-independent by construction — no lift computed from the label's
 * own (unknowable) height. `portLabelLift()` no longer exists; this table
 * is its replacement (see docs/PORT-EDGE-PLAN.md's own note on this).
 */
export const TEXT_LAYOUT_AS_PLACEMENT: Record<
  PortTextLayout,
  { origin: SlotOrigin; align: SlotAlign; offsetY: number }
> = {
  top: { origin: "top", align: "center", offsetY: 0 },
  bot: { origin: "bottom", align: "center", offsetY: 0 },
  right: { origin: "right", align: "center", offsetY: 0 },
  left: { origin: "left", align: "center", offsetY: 0 },
  rightOffset: { origin: "right", align: "end", offsetY: -PORT_LABEL_GAP },
  leftOffset: { origin: "left", align: "end", offsetY: -PORT_LABEL_GAP },
};

/** The same compatibility read for the secondary slot's own four-member
 *  enum — every member is a corner hug, so none is "lifted". */
export const SECONDARY_LAYOUT_AS_ORIGIN: Record<SecondarySlotLayout, SlotOrigin> = {
  leftOffset: "left",
  rightOffset: "right",
  topOffset: "top",
  botOffset: "bottom",
};

"use client";

// src/components/port.tsx — ported by value from packages/bbox-ui/src/port.tsx
// (docs/PORT-EDGE-PLAN.md Phase 1). `Port` is the geometry alone: the disc,
// the 2px surface ring, the 3px state ring, the lit core, the 40px hit halo.
// It knows nothing about labels or slots — `./labeledPort.tsx` is the
// composite that adds those.
//
// What ported OVER verbatim (pure geometry/paint, no schema): `portDotClass`,
// the ring/halo/core layering.
//
// What's LEFT BEHIND (docs/PORT-EDGE-PLAN.md's own list — none of it is
// geometry): `resolveField`/`PORT_PRESETS`/the `size` cascade rung (D4 —
// `diameter` is a direct prop here), `tone`/`lens`/`reveal`/`producers` (D3 —
// the sketch's six states don't need them, each is re-addable later), and
// `anchored` (wall geometry for a real Block).

import type { ComponentProps, CSSProperties } from "react";

import { cn } from "../lib/utils";
import { PORT_DIAMETERS, PORT_HIT_PX, PORT_STATE_RING_PX, PORT_SURFACE_RING_PX, type PortSize } from "./port.layout";

/* ------------------------------------------------------------------ */
/* Colour — state -> token, inlined from packages/bbox-ui's appearance.ts */
/* (STATE_TOKENS/paintVar), tone channel removed (D3) so there is no      */
/* color-mix blend step: a token resolves straight to `var(--token)`.     */
/* ------------------------------------------------------------------ */

/**
 * The board's four-value axis — "what is in the port": empty, a default
 * value set, wired to something, or data has flowed through it just now.
 * `dimmed`/`hidden` are NOT rungs of this union (see `PortProps`'s own
 * docs) — neither is a fact about what the port IS.
 */
export type PortState = "empty" | "valueSet" | "wired" | "received";

export const PORT_STATES: PortState[] = ["empty", "valueSet", "wired", "received"];

export const PORT_STATE_LABELS: Record<PortState, string> = {
  empty: "Empty",
  valueSet: "Default Value",
  wired: "Wired",
  received: "Data Received",
};

interface StateTokenPair {
  ring: string | null;
  fill: string | null;
  core: string | null;
}

const STATE_TOKENS: Record<PortState, StateTokenPair> = {
  empty: { ring: "foreground", fill: null, core: null },
  valueSet: { ring: "muted-foreground", fill: "muted", core: null },
  wired: { ring: "primary", fill: null, core: "primary" },
  received: { ring: "bbox-received", fill: "bbox-received", core: "bbox-received" },
};

/**
 * `primary` resolves through the bbox accent (with a fallback to whatever
 * host `--primary` already means) so "wired" reads as the design system's
 * own orange rather than the host's button colour — same special case
 * `paintVar` makes in the donor package. `--bbox-primary`/`--bbox-received`
 * are the two tokens this phase appends to `src/globals.css`.
 */
export function paintVar(token: string): string {
  return token === "primary" ? "var(--bbox-primary, var(--primary))" : `var(--${token})`;
}

/* ------------------------------------------------------------------ */
/* The dot's paint                                                     */
/* ------------------------------------------------------------------ */

export interface PortDotPaintInput {
  state?: PortState;
  dimmed?: boolean;
  hinting?: boolean;
}

/**
 * Static half of the dot's class — sizing/shape/transition only. Every
 * colour fact is dynamic per state and lives in `portDotStyle` instead.
 *
 * `hover:scale-110` is a real CSS `:hover` pseudo-class, deliberately NOT a
 * `hover` prop — nothing outside this component ever needs to SET hover.
 */
export function portDotClass(): string {
  return "relative box-border inline-flex shrink-0 rounded-full transition-transform duration-[50ms] ease-in-out hover:scale-110 motion-reduce:transition-none motion-reduce:hover:scale-100";
}

/**
 * The dot's ring/fill. `dimmed` forces the ring to `muted-foreground` and
 * fades the whole dot to ~45% opacity, leaving the resting fill/core colour
 * underneath untouched (a dimmed `wired` port still reads "wired, just not
 * focused right now"). `hinting` wears `wired`'s own shape (hollow ring, lit
 * core) in the accent colour regardless of `state` — previewing the port
 * BECOMING wired, with a wide halo.
 */
export function portDotStyle({ state = "empty", dimmed = false, hinting = false }: PortDotPaintInput): CSSProperties {
  const { ring, fill } = STATE_TOKENS[state];
  const ringColor = hinting ? paintVar("primary") : dimmed ? paintVar("muted-foreground") : ring ? paintVar(ring) : null;
  // `hinting` renders hollow (no fill), matching `wired`'s own shape.
  const fillColor = hinting ? null : fill ? paintVar(fill) : null;

  const layers: string[] = [];
  if (ringColor != null) {
    const stateRingPx = hinting ? 4 : PORT_STATE_RING_PX;
    layers.push(`0 0 0 ${PORT_SURFACE_RING_PX}px var(--card)`);
    layers.push(`0 0 0 ${PORT_SURFACE_RING_PX + stateRingPx}px ${ringColor}`);
  }
  if (hinting) {
    layers.push("0 0 0 9px color-mix(in srgb, var(--bbox-primary, var(--primary)) 38%, transparent)");
  }

  const style: CSSProperties = {};
  if (layers.length > 0) style.boxShadow = layers.join(", ");
  // Opaque resting paint, never transparent — a wall-mounted dot straddles a
  // block's border, and a transparent interior would let it show through a
  // hollow (`empty`/`wired`) dot. `var(--card)` is the same token the 2px
  // surface ring already uses, so ring and disc read as one punch-out.
  style.background = fillColor ?? "var(--card)";
  if (dimmed && !hinting) style.opacity = 0.45;
  if (hinting) style.transform = "scale(1.18)";
  return style;
}

/** The core's own diameter as a fraction of the dot's. */
const PORT_CORE_RATIO = 0.42;

/**
 * The small inner "core" dot: lit for `wired` (disc stays hollow, core lit
 * instead of a solid fill) and `received` (core matches the already-solid
 * fill, reading as "fully lit"). `null` means no core layer at all, not a
 * transparent one — `empty`/`valueSet` never mount the extra span.
 */
export function portCoreStyle({ state = "empty", hinting = false }: PortDotPaintInput): CSSProperties | null {
  const core = hinting ? "primary" : STATE_TOKENS[state].core;
  if (core == null) return null;
  return { background: paintVar(core) };
}

/* ------------------------------------------------------------------ */
/* Port — the dot alone: the disc + both rings + the lit core + the    */
/* 40px hit halo. Knows nothing about labels or slots.                 */
/* ------------------------------------------------------------------ */

export interface PortProps extends ComponentProps<"span"> {
  state?: PortState;
  diameter?: PortSize;
  /** Author-set, persisted. Genuinely absent when true — `if (hidden)
   * return null`, no element, no 40px halo, no pointer events at all. Not
   * "opacity 0, still clickable" — Zach's own annotation on the sketch:
   * "Completely remove it, we don't want it to be selectable either." */
  hidden?: boolean;
  /** Host-set, never persisted — the port is out of focus, or mid-drag and
   * not a legal target. Composes OVER the resting paint (a dimmed `wired`
   * port stays legible as "wired, unfocused"), never a fifth `state`. */
  dimmed?: boolean;
  /** Host-set, never persisted — the pointer is over this port mid-drag,
   * previewing it becoming `wired`. */
  hinting?: boolean;
}

/**
 * The dot alone. `hidden` renders NOTHING — not a fifth visual state, a
 * visibility fact (see `PortProps.hidden`'s own doc, and Port.stories.tsx's
 * `Hidden` story, which asserts the DOM node is actually gone).
 */
export function Port({
  state = "empty",
  diameter = "md",
  hidden = false,
  dimmed = false,
  hinting = false,
  className,
  style,
  ...props
}: PortProps) {
  if (hidden) return null;
  const diameterPx = typeof diameter === "number" ? diameter : PORT_DIAMETERS[diameter];
  // A fixed 40px hit target regardless of the painted diameter.
  const haloInset = (diameterPx - PORT_HIT_PX) / 2;
  const coreStyle = portCoreStyle({ state, hinting });
  return (
    <span
      data-slot="port-dot"
      data-state={state}
      data-diameter={diameter}
      data-dimmed={dimmed || undefined}
      data-hinting={hinting || undefined}
      className={cn(portDotClass(), className)}
      style={{
        width: diameterPx,
        height: diameterPx,
        ...portDotStyle({ state, dimmed, hinting }),
        ...style,
      }}
      {...props}
    >
      <span data-slot="port-dot-halo" aria-hidden className="absolute rounded-full" style={{ inset: haloInset }} />
      {coreStyle && (
        <span
          data-slot="port-dot-core"
          aria-hidden
          className="pointer-events-none absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full"
          style={{ width: `${PORT_CORE_RATIO * 100}%`, height: `${PORT_CORE_RATIO * 100}%`, ...coreStyle }}
        />
      )}
    </span>
  );
}

